import { Component, OnDestroy } from '@angular/core';

interface Slide {
  id: number;
  title: string;
  imageUrl: string;
}

const AUTOPLAY_MS = 1000;

@Component({
  selector: 'app-root',
  standalone: true,
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements OnDestroy {
  slides: Slide[] = [
    {
      id: 1,
      title: 'Snowflakes glowing under city lights',
      imageUrl: 'https://picsum.photos/seed/slide-1/800/400'
    },
    {
      id: 2,
      title: 'Forest trail in the morning',
      imageUrl: 'https://images.pexels.com/photos/1563604/pexels-photo-1563604.jpeg'
    },
    {
      id: 3,
      title: 'City lights at night',
      imageUrl: 'https://images.pexels.com/photos/220067/pexels-photo-220067.jpeg'
    }
  ];

  currentIndex = 0;
  playing = false;

  private timer: ReturnType<typeof setTimeout> | undefined;

  get totalSlides(): number {
    return this.slides.length;
  }

  get currentSlide(): Slide | null {
    return this.slides[this.currentIndex] ?? null;
  }

  get canGoPrev(): boolean {
    return this.currentIndex > 0;
  }

  get canGoNext(): boolean {
    return this.currentIndex < this.totalSlides - 1;
  }

  get canPlay(): boolean {
    return this.totalSlides >= 2;
  }

  goTo(index: number): void {
    if (index < 0 || index >= this.totalSlides) return;
    this.currentIndex = index;
    this.restartTimer();
  }

  prev(): void {
    if (this.canGoPrev) this.goTo(this.currentIndex - 1);
  }

  next(): void {
    if (this.canGoNext) this.goTo(this.currentIndex + 1);
  }

  togglePlaying(): void {
    this.playing = !this.playing;
    this.restartTimer();
  }

  removeCurrent(): void {
    this.slides = this.slides.filter((_, index) => index !== this.currentIndex);
    this.currentIndex = Math.max(0, Math.min(this.currentIndex, this.totalSlides - 1));
    if (!this.canPlay) this.playing = false;
    this.restartTimer();
  }

  onKeydown(event: KeyboardEvent): void {
    if (event.key === 'ArrowRight') this.next();
    else if (event.key === 'ArrowLeft') this.prev();
    else if (event.key === 'Home') this.goTo(0);
    else if (event.key === 'End') this.goTo(this.totalSlides - 1);
    else return;
    event.preventDefault();
  }

  ngOnDestroy(): void {
    clearTimeout(this.timer);
  }

  // One timer, restarted after every move, so a slide never jumps right after the user moved it.
  private restartTimer(): void {
    clearTimeout(this.timer);
    if (!this.playing) return;
    this.timer = setTimeout(() => {
      this.currentIndex = (this.currentIndex + 1) % this.totalSlides;
      this.restartTimer();
    }, AUTOPLAY_MS);
  }
}

